ALTER TABLE public.posts ADD COLUMN is_hidden boolean NOT NULL DEFAULT false;
CREATE TABLE public.account_moderation (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), suspended boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_moderation TO authenticated;
GRANT ALL ON public.account_moderation TO service_role;
ALTER TABLE public.account_moderation ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin account review" ON public.account_moderation FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.account_active(uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.account_moderation WHERE user_id=uid AND suspended) $$;
CREATE TABLE public.reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, reporter_id uuid NOT NULL REFERENCES public.profiles(id), reason text NOT NULL, details text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved','dismissed')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, UNIQUE(post_id,reporter_id), CHECK(length(details)<=2000), CHECK(reason IN ('Spam','Harassment','Inappropriate content','Misleading history','Other')));
GRANT SELECT,INSERT ON public.reports TO authenticated;
GRANT ALL ON public.reports TO service_role;
ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own report read" ON public.reports FOR SELECT TO authenticated USING (reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "submit report" ON public.reports FOR INSERT TO authenticated WITH CHECK (reporter_id=auth.uid() AND status='open' AND reviewed_at IS NULL AND public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.posts WHERE id=post_id AND NOT is_hidden));
CREATE TABLE public.moderation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL, action text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.moderation_actions TO authenticated;
GRANT ALL ON public.moderation_actions TO service_role;
ALTER TABLE public.moderation_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin history" ON public.moderation_actions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, kind text NOT NULL CHECK(kind IN ('like','comment','follow','moderation')), post_id uuid REFERENCES public.posts(id) ON DELETE CASCADE, message text NOT NULL DEFAULT '', is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notifications TO authenticated;
GRANT UPDATE(is_read) ON public.notifications TO authenticated;
GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notifications" ON public.notifications FOR SELECT TO authenticated USING(recipient_id=auth.uid());
CREATE POLICY "read own notifications" ON public.notifications FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
CREATE INDEX notifications_recipient_date ON public.notifications(recipient_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.notify_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE recipient uuid; actor uuid; target uuid; event_kind text;
BEGIN
 IF TG_TABLE_NAME='follows' THEN recipient:=NEW.following_id; actor:=NEW.follower_id; event_kind:='follow';
 ELSE SELECT user_id INTO recipient FROM public.posts WHERE id=NEW.post_id AND NOT is_hidden; actor:=NEW.user_id; target:=NEW.post_id; event_kind:=CASE WHEN TG_TABLE_NAME='likes' THEN 'like' ELSE 'comment' END; END IF;
 IF recipient IS NOT NULL AND recipient<>actor THEN INSERT INTO public.notifications(recipient_id,actor_id,kind,post_id) VALUES(recipient,actor,event_kind,target); END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER notify_like AFTER INSERT ON public.likes FOR EACH ROW EXECUTE FUNCTION public.notify_activity();
CREATE TRIGGER notify_comment AFTER INSERT ON public.comments FOR EACH ROW EXECUTE FUNCTION public.notify_activity();
CREATE TRIGGER notify_follow AFTER INSERT ON public.follows FOR EACH ROW EXECUTE FUNCTION public.notify_activity();
DROP POLICY "posts readable" ON public.posts;
CREATE POLICY "visible posts" ON public.posts FOR SELECT USING(NOT is_hidden);
CREATE POLICY "own hidden posts" ON public.posts FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
REVOKE UPDATE ON public.posts FROM authenticated;
GRANT UPDATE(title,story,era,location,category,image_url) ON public.posts TO authenticated;
DROP POLICY "own posts insert" ON public.posts;
CREATE POLICY "own posts insert" ON public.posts FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND NOT is_hidden AND public.account_active(auth.uid()));
DROP POLICY "own posts update" ON public.posts;
CREATE POLICY "own posts update" ON public.posts FOR UPDATE TO authenticated USING(auth.uid()=user_id AND public.account_active(auth.uid())) WITH CHECK(auth.uid()=user_id AND public.account_active(auth.uid()));
DROP POLICY "comments readable" ON public.comments;
CREATE POLICY "visible comments" ON public.comments FOR SELECT USING(EXISTS(SELECT 1 FROM public.posts WHERE id=post_id AND NOT is_hidden) OR public.has_role(auth.uid(),'admin'));
DROP POLICY "own comments ins" ON public.comments;
CREATE POLICY "own comments ins" ON public.comments FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.posts WHERE id=post_id AND NOT is_hidden));
DROP POLICY "own likes ins" ON public.likes;
CREATE POLICY "own likes ins" ON public.likes FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.posts WHERE id=post_id AND NOT is_hidden));
DROP POLICY "own follows ins" ON public.follows;
CREATE POLICY "own follows ins" ON public.follows FOR INSERT TO authenticated WITH CHECK(auth.uid()=follower_id AND public.account_active(auth.uid()));
DROP POLICY "own saves ins" ON public.saves;
CREATE POLICY "own saves ins" ON public.saves FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.posts WHERE id=post_id AND NOT is_hidden));
CREATE POLICY "avatars readable" ON storage.objects FOR SELECT USING(bucket_id='avatars');
CREATE POLICY "own avatar upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text AND public.account_active(auth.uid()));
CREATE POLICY "own avatar delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
DROP POLICY "post images public read" ON storage.objects;
CREATE POLICY "visible post images" ON storage.objects FOR SELECT USING(bucket_id='post-images' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.posts WHERE image_url=name AND NOT is_hidden)));
DROP POLICY "post images own upload" ON storage.objects;
CREATE POLICY "post images own upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='post-images' AND (storage.foldername(name))[1]=auth.uid()::text AND public.account_active(auth.uid()));